@extends('layouts.app')@section('title','Your shopping bag')@section('content')<main><div class="page-heading"><h1>Your shopping bag</h1><span>{{ $items->sum('quantity') }} items</span></div>@if($items->count())<div class="checkout-layout"><div class="cart-list">@foreach($items as $i)<article class="cart-item"><img src="{{ optional($i->product)->image }}" alt="{{ optional($i->product)->name }}"><div><h3>{{ optional($i->product)->name??'Unavailable product' }}</h3><small>{{ $i->variant }}</small><p>{{ $money(optional($i->product)->price??0) }}</p><form method="post" action="{{ route('cart.remove',$i->id) }}">@csrf @method('DELETE')<button class="text-link">Remove</button></form></div><form class="quantity" method="post" action="{{ route('cart.update',$i->id) }}">@csrf<input type="number" aria-label="Quantity" name="quantity" min="1" max="{{ optional($i->product)->available_stock??1 }}" value="{{ $i->quantity }}"><button>Update</button></form><strong>{{ $money((optional($i->product)->price??0)*$i->quantity) }}</strong></article>@endforeach<div class="actions"><a class="outline" href="/shop">Continue shopping</a><form method="post" action="{{ route('cart.clear') }}">@csrf<button class="text-link">Clear bag</button></form></div></div>@include('shop.summary')</div>@else<div class="empty"><h2>Your bag is empty</h2><p>Find something you love in the collection.</p><a class="primary" href="/shop">Explore products</a></div>@endif</main>@endsection
